function openStatusSheet(kind){const sheet=$('#statusSheet'),rows=$('#statusSheetRows'),m=dashboardMetrics;if(!m){toast('Data dashboard masih dimuat. Coba beberapa saat lagi.');return}rows.replaceChildren();const isSales=kind==='sales',data=isSales?[['T','Tunai',m.salesBreakdown?.cash??0,'deal'],['K','Kredit',m.salesBreakdown?.credit??0,'medium']]:[['L','Low',m.breakdown?.low??0,'low'],['M','Medium',m.breakdown?.medium??0,'medium'],['H','Hot',m.breakdown?.hot??0,'hot'],['D','Deal',m.breakdown?.deal??0,'deal'],['X','Lost',m.breakdown?.lost??0,'lost']];$('#statusSheetTitle').textContent=isSales?'Unit Terjual':'Status Prospek';$('#statusSheetSubtitle').textContent='Data ASSIST · Bulan berjalan';$('#statusSheetSummaryLabel').textContent=isSales?'Total unit terjual':'Total prospek aktif';$('#statusSheetTotal').textContent=isSales?m.deals:m.prospects;$('#statusSheetUnit').textContent=isSales?'Unit':'Prospek';for(const [icon,label,total,cls] of data){const row=document.createElement('div'),badge=document.createElement('span'),name=document.createElement('b'),value=document.createElement('strong');row.className='sheet-status-row';badge.className=`sheet-badge ${cls}`;badge.textContent=icon;name.textContent=label;value.textContent=total;row.append(badge,name,value);rows.append(row)}rows.hidden=false;sheet.showModal()}function bindCardSheet(id,kind){const el=$(id);el.onclick=()=>openStatusSheet(kind);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openStatusSheet(kind)}}}bindCardSheet('#salesTargetCard','sales');bindCardSheet('#prospectTargetCard','prospect');$('#statusSheet .sheet-close').onclick=()=>$('#statusSheet').close();$('#statusSheet').onclick=e=>{if(e.target===$('#statusSheet'))$('#statusSheet').close()};

let activeSalesGeneration=0,activeSalesId=null,activeSalesJob=null;
async function setupActiveSales(){const box=$('#adminSalesSwitcher'),sel=$('#activeSalesSelect');box.hidden=false;sel.replaceChildren();try{const b=await api('/api/admin/users?status=ACTIVE'),sales=b.users.filter(x=>x.role==='SALES');for(const u of sales)sel.append(new Option(`${u.fullName} · ${u.salesCode}`,u.id));if(!sales.length){sel.append(new Option('Belum ada akun Sales',''));$('#dashboardAssistStatus').textContent='Belum ada Sales';return}activeSalesId=sel.value;salesDataGeneration++;await loadActiveSalesDashboard()}catch{$('#dashboardAssistStatus').textContent='Daftar Sales gagal dimuat'}}
async function loadActiveSalesDashboard(){const id=$('#activeSalesSelect').value;if(!id)return;activeSalesId=id;const generation=++activeSalesGeneration;$('#dashboardAssistStatus').textContent='Memuat akun…';for(const x of ['dashboardProspects','dashboardTargetProspect','dashboardDeals','dashboardTargetUnit','dashboardCash','dashboardCredit','dashboardLeads'])$(`#${x}`).textContent='…';try{const b=await api(`/api/admin/sales/${encodeURIComponent(id)}/dashboard`);if(generation!==activeSalesGeneration||id!==activeSalesId)return;const u=b.sales,m=b.metrics;dashboardMetrics=m;$('#welcome').textContent=u.fullName;$('#salesIdentity').textContent=`${u.salesCode} · ${u.dealerCode} · SALES`;$('#salesAvatar').textContent=(u.fullName||'S').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();$('#dashboardAssistStatus').textContent=b.connection?.status==='CONNECTED'?`Terhubung · ${b.connection.displayName||u.fullName}`:'Belum terhubung';$('#dashboardAssistDot').classList.toggle('connected',b.connection?.status==='CONNECTED');$('#activeSalesConnectForm').hidden=b.connection?.status==='CONNECTED';$('#dashboardProspects').textContent=m.prospects;$('#dashboardTargetProspect').textContent=m.targetProspect;$('#dashboardDeals').textContent=m.deals;$('#dashboardTargetUnit').textContent=m.targetUnit;$('#dashboardCash').textContent=m.salesBreakdown?.cash??'—';$('#dashboardCredit').textContent=m.salesBreakdown?.credit??'—';$('#dashboardLeads').textContent=m.leadsNew+m.leadsOnTrack;$('#dashboardWorkloadCount').textContent=m.workload}catch(e){if(generation!==activeSalesGeneration)return;dashboardMetrics=null;$('#dashboardAssistStatus').textContent=e.code==='ASSIST_REAUTH_REQUIRED'?'Belum terhubung':'Data gagal dimuat';$('#activeSalesConnectForm').hidden=false;for(const x of ['dashboardProspects','dashboardTargetProspect','dashboardDeals','dashboardTargetUnit','dashboardCash','dashboardCredit','dashboardLeads','dashboardWorkloadCount'])$(`#${x}`).textContent='—'}}
$('#activeSalesSelect').onchange=()=>{activeSalesId=$('#activeSalesSelect').value;activeSalesGeneration++;loadActiveSalesDashboard()};
$('#activeSalesConnectForm').onsubmit=async e=>{e.preventDefault();if(!activeSalesId)return;const pass=e.target.elements.password;try{const b=await api(`/api/admin/sales/${encodeURIComponent(activeSalesId)}/assist-login-jobs`,{method:'POST',body:JSON.stringify(formData(e.target))});pass.value='';activeSalesJob=b.job.id;pollActiveSalesJob(activeSalesId,b.job.id)}catch(x){pass.value='';toast(x.code||'Login ASSIST gagal')}};
async function pollActiveSalesJob(salesId,jobId){try{const b=await api(`/api/admin/sales/${encodeURIComponent(salesId)}/assist-login-jobs/${encodeURIComponent(jobId)}`),j=b.job;if(salesId!==activeSalesId)return;if(j.status==='MFA_REQUIRED'){$('#activeSalesMfa').hidden=false;$('#activeSalesMfaNumber').textContent=j.mfaNumber||'Setujui notifikasi'}if(['QUEUED','RUNNING','MFA_REQUIRED'].includes(j.status)){setTimeout(()=>pollActiveSalesJob(salesId,jobId),2000);return}$('#activeSalesMfa').hidden=true;if(j.status==='SUCCEEDED'){toast('ASSIST Sales berhasil terhubung');loadActiveSalesDashboard()}else toast(({INVALID_ASSIST_CREDENTIALS:'Password ASSIST salah',ACCOUNT_NOT_FOUND:'Akun Microsoft tidak ditemukan',PASSWORD_STEP_TIMEOUT:'Halaman password Microsoft tidak muncul',MFA_NOT_AVAILABLE:'Kode MFA tidak tersedia. Periksa metode Authenticator akun ini.'})[j.errorCode]||j.errorCode||'Login ASSIST gagal')}catch{toast('Status login ASSIST gagal dimuat')}}
